param(
    [string]$Model = "qwen2.5:3b",
    [switch]$SkipOllamaInstall,
    [switch]$SkipModelPull
)

# Self-Hosted AI Office Part B Local Inference Runtime Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found at E:\AI\AI-Office" }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\self-hosting-part-b-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
foreach ($Directory in @(
 "config\self-hosting",
 "workspace\self-hosting\health",
 "workspace\self-hosting\inference-results",
 "workspace\templates",
 "scripts\self-hosting",
 "docs"
)) { New-Item -ItemType Directory -Path (Join-Path $Repository $Directory) -Force | Out-Null }
function Write-EmbeddedFile {
 param([string]$RelativePath,[string]$Base64Content)
 $Destination = Join-Path $Repository $RelativePath
 $Parent = Split-Path -Parent $Destination
 if ($Parent -and -not (Test-Path -LiteralPath $Parent)) { New-Item -ItemType Directory -Path $Parent -Force | Out-Null }
 if (Test-Path -LiteralPath $Destination -PathType Leaf) {
   $BackupPath = Join-Path $BackupDirectory $RelativePath
   $BackupParent = Split-Path -Parent $BackupPath
   if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) { New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null }
   Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
 }
 [IO.File]::WriteAllBytes($Destination,[Convert]::FromBase64String($Base64Content))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\self-hosting\runtime-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "config\self-hosting\runtime-health-schema.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "config\self-hosting\inference-result-schema.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "workspace\templates\self-hosting-runtime-health-template.json" -Base64Content "ewogICJoZWFsdGhfaWQiOiAiU0hIRUFMVEgtWVlZWU1NREQtSEhNTVNTLUFCQzEyMyIsCiAgInByb3ZpZGVyX3R5cGUiOiAib2xsYW1hIiwKICAiZW5kcG9pbnQiOiAiaHR0cDovLzEyNy4wLjAuMToxMTQzNCIsCiAgInN0YXR1cyI6ICJ1bmtub3duIiwKICAibW9kZWxzIjogW10sCiAgImNoZWNrZWRfYXQiOiAiIgp9Cg=="
Write-EmbeddedFile -RelativePath "workspace\templates\self-hosting-inference-result-template.json" -Base64Content "ewogICJpbmZlcmVuY2VfaWQiOiAiU0hJTkYtWVlZWU1NREQtSEhNTVNTLUFCQzEyMyIsCiAgInByb3ZpZGVyX3R5cGUiOiAib2xsYW1hIiwKICAibW9kZWwiOiAiIiwKICAicHJvbXB0IjogIiIsCiAgInJlc3BvbnNlIjogIiIsCiAgInN0YXR1cyI6ICJjb21wbGV0ZWQiLAogICJtZXRyaWNzIjoge30sCiAgImNyZWF0ZWRfYXQiOiAiIgp9Cg=="
Write-EmbeddedFile -RelativePath "scripts\self-hosting\AIOfficeLocalInference.Common.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\Install-AIOfficeOllamaRuntime.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\Sync-AIOfficeOllamaModels.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\Install-AIOfficeDefaultLocalModel.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\Test-AIOfficeLocalInferenceHealth.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\Invoke-AIOfficeLocalInference.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\Initialize-AIOfficeLocalInferenceRuntime.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\self-hosting\Test-AIOfficeLocalInferenceRuntime.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\Self-Hosted-AI-Office-Part-B-Local-Inference-Runtime.md" -Base64Content ""
$Scripts = @(
 "E:\AI\AI-Office\scripts\self-hosting\AIOfficeLocalInference.Common.ps1",
 "E:\AI\AI-Office\scripts\self-hosting\Install-AIOfficeOllamaRuntime.ps1",
 "E:\AI\AI-Office\scripts\self-hosting\Sync-AIOfficeOllamaModels.ps1",
 "E:\AI\AI-Office\scripts\self-hosting\Install-AIOfficeDefaultLocalModel.ps1",
 "E:\AI\AI-Office\scripts\self-hosting\Test-AIOfficeLocalInferenceHealth.ps1",
 "E:\AI\AI-Office\scripts\self-hosting\Invoke-AIOfficeLocalInference.ps1",
 "E:\AI\AI-Office\scripts\self-hosting\Initialize-AIOfficeLocalInferenceRuntime.ps1",
 "E:\AI\AI-Office\scripts\self-hosting\Test-AIOfficeLocalInferenceRuntime.ps1"
)
foreach ($ScriptPath in $Scripts) {
 $Tokens=$null; $ParseErrors=$null
 [System.Management.Automation.Language.Parser]::ParseFile($ScriptPath,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
 if ($ParseErrors.Count -gt 0) { throw ("Syntax error in " + $ScriptPath + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; ")) }
}

# Persist chosen model into the runtime policy before initialization.
$PolicyPath = "E:\AI\AI-Office\config\self-hosting\runtime-policy.json"
$Policy = Get-Content -LiteralPath $PolicyPath -Raw | ConvertFrom-Json
$Policy.default_model = $Model
$Policy | ConvertTo-Json -Depth 50 | Set-Content -LiteralPath $PolicyPath -Encoding UTF8

& "E:\AI\AI-Office\scripts\self-hosting\Initialize-AIOfficeLocalInferenceRuntime.ps1" `
    -Model $Model `
    -SkipInstall:$SkipOllamaInstall `
    -SkipModelPull:$SkipModelPull | Out-Null

Write-Host ""
Write-Host "Self-Hosted AI Office Part B Local Inference Runtime installed successfully." -ForegroundColor Green
Write-Host "Local model: $Model" -ForegroundColor Cyan
Write-Host "Endpoint: http://127.0.0.1:11434" -ForegroundColor Cyan
Write-Host "Backups: $BackupDirectory" -ForegroundColor DarkCyan